     datasource:
       url: jdbc:mysql://127.0.0.1:3306/database_name?useUnicode=true&characterEncoding=utf-8&useSSL=false&serverTimezone=UTC
       username: root
       password: database_password
       driver-class-name: com.mysql.cj.jdbc.Driver
   
   mybatis:
