  @RestController
  public class UserController {
  
      @Autowired
      UserMapper userMapper;
  
      @GetMapping("/hello")
      public String Hello(){
          return "Hello World!!";
      }
  
      @GetMapping("/query")
      public String queryUserById(@RequestParam("id") Integer id){
          return userMapper.queryUserById(id).toString();
      }
  
      @GetMapping("/query/{id}")
      public String queryUser(@PathVariable("id") Integer id){
          return userMapper.queryUserById(id).toString();
      }
  
      @GetMapping("/queryall")
      public List<User> queryUserList(){
          List<User> users = userMapper.queryUserList();
          for (User user : users) {
              System.out.println(user);
          }
          return users;
      }
  }
  
