```

创建helloset.js

```
function hellosettest(){
    var set = new Set();
    set.add(1);
    console.log(set.values());
    console.log(set.has(1));
    console.log(set.size());
    set.add(2);
    console.log(set.values());
    console.log(set.has(2));
    console.log(set.size());
    set.delete(1);
    console.log(set.values());
    console.log(set.has(2));
    console.log(set.size());
    set.delete(2);
    console.log(set.values());
    console.log(set.has(2));
    console.log(set.size());
    console.log("------------------------------------");
    set.add("aaaaaaaaa");
    set.add("bbbbbbbbb");
    set.add("ccccccccc");
    set.add("eeeeeeeee");
    set.add("fffffffff");
    set.add("ggggggggg");
    console.log(set.has("aaaaaaaaa"));
    console.log(set.has("aaaaaaaaaaaaa"));
    console.log(set.values());
    console.log(set.size());

    console.log(set.delete("aaaaaaaaa"));
    console.log(set.values());
    console.log(set.size());

    console.log(set.clear());
    console.log(set.values());
    console.log(set.size());
}
function Set() {
    var items = {};
    /**
     * @description 定义一个集合是否有该值的方法
     * @param {string} 值
     * @return {boolean}
     */
    this.has = value => value in items;
    /**
     * @description 添加
     */
    this.add = value => {
        if (!this.has(value)) {
            items[value] = value;

            return true;
        }

        return false;
    };
    /**
     * @description 删除
     */
    this.delete = value => {
        if (this.has(value)) {
            delete items[value];

            return true;
        }

        return false;
    };
    /**
     * @description 清除
     */
    this.clear = () => {
        items = {};

        return true;
    };
    /**
     * @description 求集合长度
     */
    this.size = () => Object.keys(items).length;
    /**
     * @description 返回集合中值的数组
     */
    this.values = () => Object.values(items);
}
```

## JavaScript

### 1. dom节点

### 1.1. **原生js**操作dom节点

#### 1.1.1. 获取子元素

##### 1.1.1.1. 直接获取该元素下的子元素

getElementsByTagName是一个方法。返回的是一个数组。在访问的时候要按数组的形式访问。

```
var a = document.getElementById("test").getElementsByTagName("div");
```

##### 1.1.1.2.通过childNodes获取子节点

得到s的全部子节点，使用childNodes获取子节点的时候，childNodes返回的是子节点的集合，是一个数组的格式。他会把换行和空格也当成是节点信息。
```
var childs = obj.childNodes;  
```

为了不显示不必须的换行的空格，我们如果要使用childNodes就必须进行必要的过滤。通过正则表达式式取掉不必要的信息。下面是过滤掉

```
//去掉换行的空格
for(var i=0; i<b.length;i++){
  if(b[i].nodeName == "#text" && !/\s/.test(b.nodeValue)){
    obj.removeChild(b[i]);
  }
}
//打印测试
for(var i=0;i<b.length;i++){
  console.log(i+"---------")
  console.log(b[i]);
}
//补充 
obj.childElementCount; 可以直接获取长度 同length
```

##### 1.1.1.3.通过children来获取子节点

利用children来获取子元素是最方便的，他也会返回出一个数组。对其获取子元素的访问只需按数组的访问形式即可。

```
var getFirstChild = obj.children[0];
```

##### 1.1.1.4. 获取第一个子节点

firstChild来获取第一个子元素，但是在有些情况下打印的时候会显示undefined，原因为firstChild和childNodes是一样的，在浏览器解析的时候会把它当换行和空格一起解析，获取到的第一个子节点，只是一个换行或者是一个空格，将firstChild和childNodes一样处理。

```
var getFirstChild = obj.firstChild;
```

使用firstElementChild来获取第一个子元素的时候，这就没有firstChild的那种情况了。会获取到父元素第一个子元素的节点 这样就能直接显示出来文本信息了。他并不会匹配换行和空格信息。

```
var getFirstChild = obj.firstElementChild;
```

##### 1.1.1.5. 获取最后一个子节点

lastChild获取最后一个子节点的方式其实和firstChild是类似的，lastElementChild和firstElementChild也是类似的。

```
var getLastChildA = obj.lastChild;
var getLastChildB = obj.lastElementChild;
```

#### 1.1.2. 获取父元素

##### 1.1.2.1. parentNode获取父节点

获取的是当前元素的直接父元素。parentNode是w3c的标准。

```
var parent = obj.parentNode;
```

##### 1.1.2.2. parentNode获取父节点

parentElement和parentNode一样，只是parentElement是ie的标准。

```
var p1 = obj.parentElement;
```

##### 1.1.2.3. offsetParent获取所有父节点

offset顾名思义便是偏移量，其实这个是于位置有关的上下级 ，直接能够获取到所有父亲节点， 这个对应的值是body下的所有节点信息。

```
var p2 = obj.offsetParent;
```

#### 1.1.3. 获取兄弟元素

##### 1.1.3.1. 先获取父节点再获取子节点来获取兄弟节点

```
var brother1 = obj.parentNode.children[1];
```

##### 1.1.3.2. 获取上一个兄弟节点

获取前一个兄弟节点的时候可以使用previousSibling和previousElementSibling。他们的区别是previousSibling会匹配字符，包括换行和空格，而不是节点。previousElementSibling则直接匹配节点。

```
var brother2 = obj.previousElementSibling;
var brother3 = obj.previousSibling;
```

##### 1.1.3.3. 获取下一个兄弟节点

同previousSibling和previousElementSibling，nextSibling和nextElementSibling也是类似的。

```
var brother4 = obj.nextElementSibling;
var brother5 = obj.nextSibling;
```

### 1.2. **jQuery**操作dom节点

```
获取父节点
jQuery.parent(expr)：找父亲节点，可以传入 expr 进行过滤，比如 $("span").parent() 或者$("span").parent(".class")
jQuery.parents(expr)：这个方法只会返回直接的孩子节点，不会返回所有的子孙节点
jQuery.parentNode：以 node[] 的形式存放父节点，如果没有父节点，则返回空数组

获取兄弟节点
jQuery.prev()`，返回上一个兄弟节点，不是所有的兄弟节点
jQuery.prevAll()，返回所有之前的兄弟节点
jQuery.next()，返回下一个兄弟节点，不是所有的兄弟节点
jQuery.nextAll()，返回所有之后的兄弟节点
jQuery.siblings()，返回所有兄弟节点，不分前后

获取子节点
jQuery.children()：获取所有直接子节点
jQuery.childNodes：以 node[] 的形式存放子节点，如果没有子节点，则返回空数组
jQuery.firstChild：获取第一个子节点
jQuery.lastChild：获取最后一个子节点
jQuery.contents：获取包含的所有内容，包括空文本
jQuery.removeChild(expr)：删除并返回指定的子节点
jQuery.replaceChild(expr)：替换并返回指定的子节点.
jQuery.contents()，返回下面的所有内容，包括节点和文本。这个方法和children()的区别就在于，包括空白文本，也会被作为一个 jQuery 对象返回，children()则只会返回节点
jQuery.find(expr)，跟jQuery.filter(expr)完全不一样：
jQuery.filter()是从初始的 jQuery 对象集合中筛选出一部分，而
jQuery.find()的返回结果不会有初始集合中的内容，比如$("p").find("span")，是从<p>元素开始找<span>，等同于$("p span")
```

