> 金额格式化

```
    function formatAmount(obj) {
        var objval = $(obj).val();
        if (objval != null && objval != "") {
            if (checkFormatAmount(objval)) {
                objval = objval.replace(",", "");
                $(obj).val(addThousandsFlag(objval));
            } else {
                alert("您输入的金额类型不对,请重新输入!");
                $(obj).val("");
            }
        } else {
            $(obj).val("0.00");
        }

    }

    function checkFormatAmount(amountValue) {
        var numRegexI = /[A-Za-z]/;
        var numRegexII = /[,.<>{}~!@#$%^&*]/;
        var numRegexIII = /(^[1-9]([0-9]+)?(\.[0-9]{1,2})?$)|(^(0){1}$)|(^[0-9]\.[0-9]([0-9])?$)/;
        amountValue = amountValue.replace(",", "");
        amountValue = amountValue.replace(".", "");
        amountValue = amountValue.replace("-", "");
        if (numRegexI.test(amountValue)) {
            return false;
        }
        if (numRegexII.test(amountValue)) {
            return false;
        }
        if (!numRegexIII.test(amountValue)) {
            return false;
        }
        return true;
    }

    function addThousandsFlag(amount) {
        //正负号标识,true为正
        var signFlag = true;
        if(amount.indexOf("-")!=-1){
            signFlag = false;
            amount = amount.replace("-","");
        }
        amount = parseFloat(amount).toFixed(2);
        var amountArr = amount.split(".");
        var amountPre = amountArr[0];
        var amountPreArr = amountPre.split("");
        var coounter = 0;
        var loopFlag = amountPre.length;
        var returnValue = "";
        while (loopFlag > 0) {
            if (coounter == 3) {
                returnValue = amountPreArr[loopFlag - 1] + "," + returnValue;
                coounter = 0;
            } else {
                returnValue = amountPreArr[loopFlag - 1] + returnValue;
            }
            coounter++;
            loopFlag--;
        }
        if(!signFlag){
            return "-"+returnValue + "." + amountArr[1];
        }
        return returnValue + "." + amountArr[1];
    }
```

